from pathlib import Path
import hashlib,json,random,subprocess,tempfile
ROOT=Path.cwd()
work=Path(tempfile.mkdtemp(prefix='mldsa-hint-review-',dir=ROOT/'.pqc_runs'))
guard=ROOT/'verification/mldsa_osh/mldsa_hint_guard.v'
source=guard.read_bytes();(work/guard.name).write_bytes(source)
rng=random.Random(20421)
cases=[]
def invalid(y,w,k):
    cursor=0
    for stop in y[w:]:
        if stop<cursor or stop>w:return 1
        part=y[cursor:stop]
        if any(a>=b for a,b in zip(part,part[1:])):return 1
        cursor=stop
    return int(any(y[cursor:w]))
def add(lvl,y,w,k,label):cases.append((lvl,bytes(y),invalid(y,w,k),label))
for lvl,w,k,param in [(2,80,4,44),(3,55,6,65),(5,75,8,87)]:
    # Distinct boundary cases: empty groups, full omega, cross-group ordering reset,
    # terminal index 255, duplicates, descending counts, and nonzero unused padding.
    add(lvl,[0]*(w+k),w,k,'empty')
    full=list(range(w))+[0]*(k-1)+[w];add(lvl,full,w,k,'full-omega-last-poly')
    cross=[255,0]+[0]*(w-2)+[1]+[2]*(k-1);add(lvl,cross,w,k,'index-reset-per-poly')
    for stop in (w+1,255):
        y=[0]*(w+k);y[w]=stop;add(lvl,y,w,k,'count-overflow')
    for pos in range(w):
        y=[0]*(w+k);y[pos]=1;add(lvl,y,w,k,'nonzero-padding')
    for group in range(k):
        y=[0]*(w+k);y[:2]=[7,7];y[w:]=[0]*group+[2]*(k-group);add(lvl,y,w,k,'duplicate-per-poly')
        y[0]=8;add(lvl,y,w,k,'descending-per-poly')
    for group in range(k-1):
        y=[0]*(w+k);y[w+group]=1;add(lvl,y,w,k,'descending-count')
    for _ in range(1000):
        # Sample canonical groups, intentionally allowing empty and repeated counts.
        stops=sorted(rng.randrange(w+1) for _ in range(k))
        indices=[];cursor=0
        for stop in stops:indices.extend(sorted(rng.sample(range(256),stop-cursor)));cursor=stop
        y=indices+[0]*(w-len(indices))+stops;add(lvl,y,w,k,'random-canonical')
        for _ in range(2):
            z=y.copy();z[rng.randrange(w+k)]=rng.randrange(256);add(lvl,z,w,k,'random-one-byte-change')
    kat=ROOT/'third_party/mldsa_osh/upstream/KAT'/f'SigVer_signature_{param}.txt'
    for val in kat.read_text().split():
        y=list(bytes.fromhex(val)[-w-k:]);add(lvl,y,w,k,'pinned-sigver-hint');y[-1]^=1;add(lvl,y,w,k,'one-bit-count-change')
# Unsupported parameter codes must reject even an all-zero encoding.
for lvl in (0,1,4,6,7):cases.append((lvl,bytes(84),1,'unsupported-level'))
vec=''.join(f'{lvl:01x}{expected:01x}{y.hex():0>168}\n' for lvl,y,expected,_ in cases)
(work/'cases.hex').write_text(vec)
(work/'tb.v').write_text('''module tb;
reg [679:0] cases [0:%d]; reg [2:0] sec_lvl; reg [671:0] hint_bytes; wire invalid;
integer i; mldsa_hint_guard dut(sec_lvl,hint_bytes,invalid);
initial begin
$readmemh("cases.hex",cases);
for(i=0;i<%d;i=i+1)begin
sec_lvl=cases[i][678:676];hint_bytes=cases[i][671:0];#1;
if(invalid !== cases[i][672])$fatal(1,"case %%0d expected %%b observed %%b",i,cases[i][672],invalid);
end
$display("PASS %%0d independent hint encodings",i);$finish;
end
endmodule
'''%(len(cases)-1,len(cases)))
tools=Path('/workspace/shared/spectral-memory-reduction/tools/bin')
commands=[[str(tools/'iverilog'),'-g2012','-s','tb','-o','test.vvp','mldsa_hint_guard.v','tb.v'],[str(tools/'vvp'),'test.vvp']]
results=[]
for cmd in commands:
    p=subprocess.run(cmd,cwd=work,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=60)
    results.append({'argv':cmd,'returncode':p.returncode,'output':p.stdout})
    if p.returncode:break
report={'scope':'Standalone combinational checker, independent FIPS 204 Algorithm 21 oracle; not full-DUT or four-state full-design qualification','cases':len(cases),'expected_valid':sum(x[2]==0 for x in cases),'expected_invalid':sum(x[2]==1 for x in cases),'seed':20421,'oracle_source':'https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.204.pdf','commands':results,'guard_sha256':hashlib.sha256(source).hexdigest(),'cases_sha256':hashlib.sha256(vec.encode()).hexdigest(),'source_unchanged':guard.read_bytes()==source,'run_dir':str(work),'status':'PASS' if len(results)==2 and all(r['returncode']==0 for r in results) else 'FAIL'}
(work/'review.py').write_text(Path(__file__).read_text())
(work/'report.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report,indent=2))

